  for(int x=0;x<3;x++)for(int y=0;y<3;y++){var host=part(level,root,x,y);var projection=host.largeVisual();need(projection.shared().settings()==root.settings()&&projection.geometry()==geometry&&projection.anchor().equals(rootPos)&&projection.column()==x&&projection.row()==y,"all nine parts publish shared world-free root pose/role");need(projection.shared().state().getValue(NativeLargeDoorBlock.PAIRED)&&projection.shared().state().getValue(NativeLargeDoorBlock.HINGE)==net.minecraft.world.level.block.state.properties.DoorHingeSide.RIGHT&&(projection.shared().state().getValue(NativeLargeDoorBlock.HALF)==net.minecraft.world.level.block.state.properties.DoubleBlockHalf.LOWER)==(x==0&&y==0),"worker-facing actual-state properties");}
  var far=part(level,root,2,2);var heldVolume=far.fluidVolumeSnapshot();long revision=far.fluidGeometryRevision();level.setBlock(far.getBlockPos(),far.getBlockState().setValue(NativeLargeDoorBlock.OPEN,!originalState.getValue(NativeLargeDoorBlock.OPEN)),Block.UPDATE_KNOWN_SHAPE);far.refreshFluidGeometry();need(far.fluidVolumeSnapshot()==heldVolume&&far.fluidGeometryRevision()==revision&&far.largeVisual().shared().state().getValue(NativeLargeDoorBlock.OPEN)==originalState.getValue(NativeLargeDoorBlock.OPEN),"independent follower OPEN cannot change root physics");
  var worker=java.util.concurrent.CompletableFuture.supplyAsync(()->{var data=far.getModelData();var projection=data.get(NativeLargeDoorEntity.LARGE_VISUAL);return projection==far.largeVisual()&&data.get(NativeProgrammableDoorEntity.VISUAL)==projection.shared()&&data.get(NativeProgrammableDoorEntity.SETTINGS)==root.settings()&&projection.geometry().part(2,2).outline()!=null;}).get();need(worker,"actual asynchronous model-data path reads published resolved state only");
  var repeatedProjection=far.largeVisual();far.loadWithComponents(far.saveWithoutMetadata(level.registryAccess()),level.registryAccess());need(far.largeVisual()==repeatedProjection,"identical follower packets retain complete published root projection while refresh is queued");far.refreshFluidGeometry();need(far.largeVisual()==repeatedProjection&&far.fluidVolumeSnapshot()==heldVolume,"identical follower publication preserves geometry and projection identity");
