  far.containedFluids().set(0,water,level.registryAccess());BlockPos sponge=far.getBlockPos().relative(face.getCounterClockWise());var oldSponge=level.getBlockState(sponge);level.setBlock(sponge,Blocks.SPONGE.defaultBlockState(),Block.UPDATE_CLIENTS);NativeFluidSponge.changed(level,far.getBlockPos());need(far.containedFluids().get(0).isEmpty()&&far.containedFluids().raw(1).equals(opaque),"actual sponge drains only stored known water and retains opaque side");level.setBlock(sponge,oldSponge,Block.UPDATE_CLIENTS);far.containedFluids().set(1,FluidStack.EMPTY,level.registryAccess());
